// covers: integration dyna:graph.Graph.shortestPath dyna:graph.Graph.shortestPathTree dyna:graph.Graph.criticalPath -- networkx reference vectors
// Graph#shortestPath, #shortestPathTree and #criticalPath against networkx (single_source_dijkstra,
// all_shortest_paths, dag_longest_path, dag_longest_path_length, Bellman-Ford on the reversed negated DAG).
// tests/corpus/ref/graph_paths_vectors.js is generated by tests/ref/gen_graph_paths_ref_vectors.py; it stores
// only the answers. Each graph is rebuilt here from the same splitmix64 stream, and the weights are dyadic
// rationals (k / 1024 or (k - 1024) / 32), so every path sum is exact and everything compares with ===.
// A recorded path or predecessor is networkx's unique optimum (pred -2 / path null mark ties; none of the
// current specs has one). shortestPath must agree with the tree, and the tree's distances with dijkstra.
import { sections as __kitSections } from "../lib/kit.js";
const __kitS = __kitSections("test_graph_graph_paths_ref");
import { Graph } from "dyna:graph";
import V from "../corpus/ref/graph_paths_vectors.js";

let pass = 0, fail = 0;
const ok = (c, m) => { if (c) pass++; else { fail++; print("FAIL: " + m); } };
const M64 = (1n << 64n) - 1n;

function splitmix(seed) {
    let s = BigInt(seed) & M64;
    return () => {
        s = (s + 0x9E3779B97F4A7C15n) & M64;
        let z = s;
        z = ((z ^ (z >> 30n)) * 0xBF58476D1CE4E5B9n) & M64;
        z = ((z ^ (z >> 27n)) * 0x94D049BB133111EBn) & M64;
        return z ^ (z >> 31n);
    };
}

function build(spec, directed) {
    const r = splitmix(spec.seed), g = new Graph({ directed, weighted: true });
    for (let i = 0; i < spec.n; i++) g.addNode();
    for (let i = 0; i < spec.m; i++) {
        let u = Number(r() % BigInt(spec.n)), v = Number(r() % BigInt(spec.n));
        const k = Number(r() % 2048n);
        let w = k / 1024;
        if (spec.kind === "dag") {
            if (u === v) continue;
            [u, v] = [Math.min(u, v), Math.max(u, v)];
            w = spec.signed ? (k - 1024) / 32 : k / 1024;
        }
        g.addEdge(u, v, w);
        if (r() % 8n === 0n) g.addEdge(u, v, w + 0.5);
    }
    return g;
}

const same = (a, b) => a.length === b.length && a.every((x, i) => x === b[i]);

__kitS.section("segment L47", () => {
for (const c of V.sssp) {
    const s = c.spec, g = build(s, s.directed), tag = `sssp seed ${s.seed}`;
    const t = g.shortestPathTree(s.src), dj = g.dijkstra(s.src);
    ok(t.dist instanceof Float64Array && t.pred instanceof Int32Array && t.dist.length === s.n && t.pred.length === s.n, `${tag}: typed arrays of length n`);
    ok(c.dist.every((d, v) => (d === null ? t.dist[v] === Infinity : t.dist[v] === d)), `${tag}: tree distances equal networkx`);
    ok(dj.every((d, v) => d === t.dist[v]), `${tag}: tree distances equal dijkstra`);
    ok(c.pred.every((p, v) => p === -2 || t.pred[v] === p), `${tag}: unique predecessors equal networkx`);
    ok(t.pred.every((p, v) => (p === -1 ? v === s.src || t.dist[v] === Infinity : t.dist[p] < Infinity && t.dist[p] <= t.dist[v])), `${tag}: every predecessor is reached first`);
    for (const q of c.queries) {
        const r = g.shortestPath(s.src, q.dst);
        ok(q.dist === null ? r.dist === Infinity && r.path.length === 0 : r.dist === q.dist, `${tag} -> ${q.dst}: dist ${r.dist} vs ${q.dist}`);
        if (q.path) ok(same(r.path, q.path), `${tag} -> ${q.dst}: path ${r.path} vs ${q.path}`);
        if (r.path.length) {
            let back = [q.dst];
            while (back[0] !== s.src) back.unshift(t.pred[back[0]]);
            ok(same(back, r.path), `${tag} -> ${q.dst}: shortestPath follows the tree's predecessors`);
        }
    }
}
});

__kitS.section("segment L67", () => {
for (const c of V.critical) {
    const s = c.spec, g = build(s, true), tag = `critical seed ${s.seed}`, cp = g.criticalPath();
    ok(cp.length === c.length, `${tag}: length ${cp.length} vs ${c.length}`);
    if (c.path) ok(same(cp.path, c.path), `${tag}: path ${cp.path} vs ${c.path}`);
    ok(cp.dist instanceof Float64Array && cp.dist.length === s.n && c.dist.every((d, v) => cp.dist[v] === d), `${tag}: per-node longest path equals networkx`);
    ok(cp.dist[cp.path[cp.path.length - 1]] === cp.length, `${tag}: the path ends where dist peaks`);
}
});
__kitS.end();

print(`test_structures_graph_paths_ref: ${pass} passed, ${fail} failed (networkx ${V.networkx})`);
if (fail) throw new Error(`${fail} failures`);
